import{z as s,x as o,o as e,c as d,q as A,j as l,D as a,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"分布式训练收束","description":"","frontmatter":{"title":"分布式训练收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-map.md","filePath":"llm/dist-map.md","lastUpdated":1791063341000}'),n={name:"llm/dist-map.md"};function m(p,E,D,h,C,F){const B=o("Mermaid");return e(),d("div",null,[E[2]||(E[2]=A('<h1 id="分布式训练收束" tabindex="-1">分布式训练收束 <a class="header-anchor" href="#分布式训练收束" aria-label="Permalink to &quot;分布式训练收束&quot;">​</a></h1><div class="epigraph"><p>并行的本质是记账：谁持有什么状态、每步为同步付多少字节、谁在等谁、坏了丢多少——这门课教的是把这本账读全。</p><footer>—— 据本课程十三课整理</footer></div><p><a href="/llm/dist-performance-modeling">上一课</a>把单项机制合成能算的模型，分布式训练深入的课程到此收束。十二课从四轴对照走到配置搜索，本课不添新内容，把决策收成一张单：新训练按单走一遍，老训练拿单来对账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分布式训练的事故很少是「算法不对」，多数是账没记全。四类账对应四类现场事故：状态账没记全——参数、梯度、激活谁在哪份分片上说不清，于是峰值 OOM 与检查点恢复失败；通信账没记全——每步谁付什么字节、付在关键路径还是可遮，于是 MFU 卡在四成找不到刀口；时间账没记全——谁在等谁、等待落在哪条链路，于是映射与重叠白做；故障账没记全——丢了多少窗口、事件没入台账，于是同样的坏槽位反复咬人。收束课的任务是把每类事故倒推回它该被拦住的那一课。</p><p><span class="marginnote">MFU（模型浮点利用率）＝实际用掉的算力 ÷ 硬件理论峰值算力，可以理解成 GPU 的「有效出勤率」：0.5 就是 GPU 只有一半时间在真正算数，另一半花在等通信、搬数据和等待其他卡上。</span></p><h3 id="决策单" tabindex="-1">决策单 <a class="header-anchor" href="#决策单" aria-label="Permalink to &quot;决策单&quot;">​</a></h3><p>八步按依赖排。第一步定四轴与档位，对照表在<a href="/llm/dist-parallel-deep-comparison">DP/PP/TP/EP 深入对照</a>，DP 冗余的切法在<a href="/llm/dist-zero-stages">ZeRO 的各阶段</a>。第二步定激活策略，粒度与数值口径在<a href="/llm/dist-activation-recompute">激活重计算</a>。第三步定通信结构与重叠计划，四类合法结构在<a href="/llm/dist-comm-overlap">通信原语与 overlap</a>。第四步做拓扑映射，装填次序与环测在<a href="/llm/dist-topology-aware">拓扑感知的并行</a>。第五步判异构：只有多代卡或弱互连节点时按<a href="/llm/dist-heterogeneous-parallel">异构并行</a>配比，否则跳过。第六步判跨 DC：动机不成立就不开，结构选型在<a href="/llm/dist-cross-dc">跨数据中心训练</a>。第七步定容错链路与检查点间隔，四段链路在<a href="/llm/dist-fault-elastic">容错与弹性训练</a>。第八步开机前用<a href="/llm/dist-memory-budget">内存预算的完整清单</a>与<a href="/llm/dist-performance-modeling">性能建模</a>过滤，开机后用<a href="/llm/dist-mfu-case">MFU 优化案例</a>的分解与<a href="/llm/dist-debugging">分布式训练的调试</a>的对拍归因。</p>',8)),(e(),l(i,null,{default:a(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%9B%9B%E8%BD%B4%E4%B8%8E%20ZeRO%20%E6%A1%A3%E4%BD%8D%22%5D%20--%3E%20B%5B%22%E6%BF%80%E6%B4%BB%E7%B2%92%E5%BA%A6%E4%B8%8E%E6%95%B0%E5%80%BC%E5%8F%A3%E5%BE%84%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%80%9A%E4%BF%A1%E7%BB%93%E6%9E%84%E4%B8%8E%E9%87%8D%E5%8F%A0%E8%AE%A1%E5%88%92%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8B%93%E6%89%91%E6%98%A0%E5%B0%84%E4%B8%8E%E7%8E%AF%E6%B5%8B%22%5D%0A%20%20D%20--%3E%20E%7B%22%E5%BC%82%E6%9E%84%20%E6%88%96%20%E8%B7%A8%20DC%3F%22%7D%0A%20%20E%20--%3E%7C%E6%98%AF%7C%20F%5B%22%E9%85%8D%E6%AF%94%E4%B8%8E%E7%BB%93%E6%9E%84%E9%80%89%E5%9E%8B%22%5D%0A%20%20E%20--%3E%7C%E5%90%A6%7C%20G%5B%22%E5%AE%B9%E9%94%99%E9%93%BE%E8%B7%AF%E4%B8%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E9%97%B4%E9%9A%94%22%5D%0A%20%20F%20--%3E%20G%0A%20%20G%20--%3E%20H%5B%22%E5%BC%80%E6%9C%BA%E5%89%8D%3A%20%E6%98%BE%E5%AD%98%E6%B8%85%E5%8D%95%20%2B%20%E6%80%A7%E8%83%BD%E6%A8%A1%E5%9E%8B%E8%BF%87%E6%BB%A4%22%5D%0A%20%20H%20--%3E%20I%5B%22%E5%BC%80%E6%9C%BA%E5%90%8E%3A%20MFU%20%E5%88%86%E8%A7%A3%20%2B%20%E8%B0%83%E8%AF%95%E5%AF%B9%E6%8B%8D%2C%20%E8%AE%B0%E5%8F%B0%E8%B4%A6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条不变量横贯八步。第一条：同步组是合同——任何 rank 的任何分支偏离，都是全组等它；放之从进程组设计到调试的第一动作。第二条：峰值决定生死——显存与 step time 都按峰值记账，不按总和与均值。第三条：恢复时间是有效算力的一部分——检查点间隔、弹性枚举、恢复演练都是吞吐问题，不是运维点缀。高频拦错事四件：拿公式当峰值、拿均值当 P99、拿口径不一的 MFU 当排名、拿没演练过的恢复当容错。这四件在十二课里各占一课的份量，收束时并成一排。</p><p><span class="marginnote">「峰值决定生死」是最容易吃亏的一条：显存按总和看还有富余，但只要某一步的峰值顶到上限就 OOM；step time 看平均很快，尾部最慢的那一步才是真实节奏。所以两本账都要按峰值记，均值只用来发现异常。</span></p><p><span class="marginnote">对账前先验账本：同一配置重跑两次，step time 差异应落在噪声带内；超了说明有游标或干扰之类的账外变量，账不齐时一切比较皆噪音。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么按「四本账、八步单、三不变量」收，而不是按章节复述：课程里的具体数字会过时——卡型换代、互连换代、框架换代——但账本关系稳定得久：同步组是合同不随硬件变，峰值决定生死不随框架变，恢复时间进有效算力不随规模变。八步的依赖顺序就是事故的传播路径：第一步的分片下标错了，第四步的映射怎么调都在给错误的状态分布还债；第七步的检查点间隔定了，第八步的模型里丢失窗口才有数。对账因此从后往前问：MFU 分解指到哪一项、那一项的旋钮在哪一步定的、那一步的输入又是从哪一步传下来的——每一步都能指回上一步的数字，这套配置才算真的算过账。</p>',6)),(e(),l(i,null,{default:a(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E7%8E%B0%E8%B1%A1%3A%20MFU%20%E5%88%86%E8%A7%A3%E6%8C%87%E5%90%91%E6%9F%90%E4%B8%80%E9%A1%B9%22%5D%20--%3E%20W%7B%22%E8%BF%99%E4%B8%80%E9%A1%B9%E7%9A%84%E6%97%8B%E9%92%AE%E5%9C%A8%E5%93%AA%E4%B8%80%E6%AD%A5%E5%AE%9A%E7%9A%84%3F%22%7D%0A%20%20W%20--%3E%7C%E9%80%9A%E4%BF%A1%E5%8D%A0%E6%AF%94%E9%AB%98%7C%20S3%5B%22%E7%AC%AC%203%20%E6%AD%A5%3A%20%E9%80%9A%E4%BF%A1%E7%BB%93%E6%9E%84%E4%B8%8E%E9%87%8D%E5%8F%A0%E8%AE%A1%E5%88%92%22%5D%0A%20%20W%20--%3E%7C%E9%87%8D%E8%AE%A1%E7%AE%97%E5%81%8F%E5%A4%9A%7C%20S2%5B%22%E7%AC%AC%202%20%E6%AD%A5%3A%20%E6%BF%80%E6%B4%BB%E7%B2%92%E5%BA%A6%22%5D%0A%20%20W%20--%3E%7C%E7%AD%89%E5%BE%85%E8%90%BD%E5%9C%A8%E6%9F%90%E6%9D%A1%E9%93%BE%E8%B7%AF%7C%20S4%5B%22%E7%AC%AC%204%20%E6%AD%A5%3A%20%E6%8B%93%E6%89%91%E6%98%A0%E5%B0%84%22%5D%0A%20%20S3%20--%3E%20P%5B%22%E8%BF%99%E4%B8%80%E6%AD%A5%E7%9A%84%E8%BE%93%E5%85%A5%E6%95%B0%E5%AD%97%2C%20%E5%8F%88%E6%98%AF%E4%B8%8A%E4%B8%8A%E6%AD%A5%E4%BC%A0%E4%B8%8B%E6%9D%A5%E7%9A%84%3F%20%E9%80%90%E7%BA%A7%E5%9B%9E%E6%8C%87%22%5D%0A%20%20S2%20--%3E%20P%0A%20%20S4%20--%3E%20P%0A%20%20P%20--%3E%20D%5B%22%E6%AF%8F%E6%AD%A5%E9%83%BD%E6%8C%87%E5%BE%97%E5%9B%9E%E6%95%B0%E5%AD%97%2C%20%E8%BF%99%E5%A5%97%E9%85%8D%E7%BD%AE%E6%89%8D%E7%AE%97%E7%9C%9F%E7%AE%97%E8%BF%87%E8%B4%A6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">八步的依赖关系像装修水电：先走管线再铺地板，地板出了问题，砸开的往往不是地板那层。第一步分片下标错了，后面映射调得再好，都是在给错误的状态分布还债——所以对账要能从后往前指回去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程没写的：训练循环与实验管理的日常，归训练基础设施课程；RL 循环里的 rollout 与奖励服务把这套并行账再叠加一层时序账，归下一课程；数据侧的清洗与配比已有专门课程。具体框架的旋钮名与默认值不在收束单里——它们是各课口径在某一代实现上的投影，换投影不换账。对账的最后一条纪律：单子里每一步要么有数字、要么有「为什么此步跳过」的理由，空白步不算走过。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四本账：状态（谁持有什么）、通信（每步付什么字节）、时间（谁在等谁）、故障（坏了丢多少）。</li><li>决策单八步按依赖排：轴与档位、激活、重叠、映射、异构、跨 DC、容错、前后验证。</li><li>三条不变量：同步组是合同、峰值决定生死、恢复时间是有效算力的一部分。</li><li>四件高频拦错事：公式当峰值、均值当 P99、口径不一的 MFU 当排名、没演练的恢复当容错。</li><li>出处：按本课程十三课整理；各项机制口径见各课出处行。</li></ul>',5))])}const c=s(n,[["render",m]]);export{_ as __pageData,c as default};
